insert into public.kpi_org_links(organization_id,kpi_id,org_unit_id,position_id)
select k.organization_id,k.id,case when m.position_title is null then u.id end,p.id
from mapping m join public.kpis k on k.code=m.code
join public.org_units u on u.organization_id=k.organization_id and u.name=m.unit_name
left join public.positions p on p.organization_id=k.organization_id and p.org_unit_id=u.id and p.title=m.position_title
